<?php declare(strict_types=1);require_once __DIR__.'/../includes/admin-auth.php';$users=load_json('users.json',[]);$downloads=load_json('downloads.json',[]);$releases=load_json('releases.json',[]);$today=date('Y-m-d');$month=date('Y-m');$monthly=array_filter($downloads,fn($d)=>is_array($d)&&str_starts_with((string)$d['downloaded_at'],$month));$todayCount=array_filter($downloads,fn($d)=>is_array($d)&&str_starts_with((string)$d['downloaded_at'],$today));?><main class="admin-shell"><aside class="admin-sidebar" data-admin-sidebar><div class="admin-brand"><a class="brand" href="<?= e(app_url('index.php')) ?>"><span class="brand-mark"><i></i><i></i></span><span>2B2X</span></a></div><nav class="admin-nav"><a class="active" href="<?= e(app_url('admin/index.php')) ?>">Dashboard</a><a href="<?= e(app_url('admin/users.php')) ?>">Users</a><a href="<?= e(app_url('admin/releases.php')) ?>">Releases</a><a href="<?= e(app_url('admin/downloads.php')) ?>">Downloads</a><a href="<?= e(app_url('admin/changelog.php')) ?>">Changelog</a><a href="<?= e(app_url('admin/blog.php')) ?>">Blog</a><a href="<?= e(app_url('admin/support.php')) ?>">Support</a><a href="<?= e(app_url('admin/settings.php')) ?>">Settings</a></nav><div class="admin-sidebar-footer"><a class="button button-ghost button-small" href="<?= e(app_url('admin/logout.php')) ?>">Logout</a></div></aside><div class="admin-main"><header class="admin-topbar"><button class="menu-toggle" data-admin-toggle aria-label="Open admin menu"><span></span><span></span></button><div><h1>Control center</h1><small style=color:var(--subtle)>Product operations · 2B2X Browser</small></div><div class="admin-topbar-actions"><span class="status-pill">System online</span><a class="button button-primary button-small" href="<?= e(app_url('admin/releases.php?new=1')) ?>">New release</a></div></header><div class="admin-content"><section class="admin-metrics"><div class="admin-metric reveal" data-reveal><span>Total users</span><strong><?= count(array_filter($users,fn($u)=>is_array($u))) ?></strong><small>Registered accounts</small></div><div class="admin-metric reveal reveal-delay-1" data-reveal><span>Total downloads</span><strong><?= count($downloads) ?></strong><small>All-time activity</small></div><div class="admin-metric reveal reveal-delay-2" data-reveal><span>Downloads today</span><strong><?= count($todayCount) ?></strong><small>Current day</small></div><div class="admin-metric reveal reveal-delay-3" data-reveal><span>Current version</span><strong><?= e((string)current_release()['version']??'1.0.0') ?></strong><small>Published release</small></div></section><section class="admin-grid"><div class="admin-card reveal" data-reveal><h2>Download activity</h2><p>Recent installation requests across the current release.</p><div class="chart"><canvas data-chart="downloads" aria-label="Download chart"></canvas></div><div class="chart-legend"><span><i class=eyebrow-dot></i>Downloads</span><span>30-day view</span></div></div><div class="admin-card reveal reveal-delay-1" data-reveal><h2>Release health</h2><p>Current publication state.</p><div class="mini-stat"><span>Published</span><strong><?= count(array_filter($releases,fn($r)=>is_array($r)&&($r['is_published']??false))) ?></strong></div><div class="mini-stat"><span>Latest</span><strong><?= count(array_filter($releases,fn($r)=>is_array($r)&&($r['is_latest']??false))) ?></strong></div><div class="mini-stat"><span>Files indexed</span><strong><?= count(array_filter($releases,fn($r)=>is_array($r)&&!empty($r['filename']))) ?></strong></div><div class="mini-stat"><span>Monthly downloads</span><strong><?= count($monthly) ?></strong></div></div></section><section class="admin-card admin-table-card reveal" data-reveal><h2>Recent releases</h2><p>Latest product updates and publication status.</p><div class="table-wrap"><table><thead><tr><th>Version</th><th>Title</th><th>Architecture</th><th>Published</th><th>Latest</th></tr></thead><tbody><?php if(!$releases):?><tr><td colspan=5><div class="empty-state"><h3>No releases found</h3><p<Create the first release to publish it.</p></div></td></tr><?php else:foreach(array_slice(array_reverse($releases),0,5) as $release):?><tr><td><strong><?= e((string)$release['version']) ?></strong></td><td><?= e((string)$release['title']) ?></td><td><?= e((string)$release['architecture']) ?></td><td><span class="status-badge <?= ($release['is_published']??false)?'status-active':'status-pending' ?>"><?= ($release['is_published']??false)?'Published':'Draft' ?></span></td><td><?= ($release['is_latest']??false)?'<span class=status-badge status-active>Yes</span>':'—' ?></td></tr><?php endforeach;endif; ?></tbody></table></div></section></div></div></main><script src="<?= e(app_url('assets/js/charts.js')) ?>" defer></script><?php require_once __DIR__.'/../includes/footer.php'; ?>
